INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MongoDB > Objekte (Index, Aggregation Pipeline)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Verbessert ein Index in MongoDB die Abfrageleistung für häufig genutzte Felder?', 2, '[{"text": "Ja", "correct": true, "because": "Indizes beschleunigen Abfragen"}, {"text": "Nein", "correct": false, "because": "Hauptzweck von Indizes"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Index in MongoDB auf mehreren Feldern gleichzeitig erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Compound Indexes sind möglich"}, {"text": "Nein", "correct": false, "because": "Mehrere Felder unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Erlaubt die Aggregation Pipeline in MongoDB die Verarbeitung von Daten in mehreren Schritten?', 2, '[{"text": "Ja", "correct": true, "because": "Pipeline besteht aus Stufen"}, {"text": "Nein", "correct": false, "because": "Mehrstufige Verarbeitung ist Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss jede Aggregation Pipeline in MongoDB immer mit einem $match-Operator beginnen?', 2, '[{"text": "Nein", "correct": true, "because": "Pipeline-Stufen sind flexibel"}, {"text": "Ja", "correct": false, "because": "Start ist variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Indizes in MongoDB die Schreibleistung einer Datenbank negativ beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Indexpflege kostet Ressourcen"}, {"text": "Nein", "correct": false, "because": "Schreiboperationen werden verlangsamt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Objekt in MongoDB wird verwendet, um die Abfrageleistung zu optimieren?', 2, '[{"text": "Index", "correct": true, "because": "Beschleunigt Abfragen"}, {"text": "Aggregation Pipeline", "correct": false, "because": "Datenverarbeitung"}, {"text": "Collection", "correct": false, "because": "Datencontainer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Index in MongoDB kombiniert mehrere Felder für eine Abfrage?', 3, '[{"text": "Compound Index", "correct": true, "because": "Mehrere Felder indiziert"}, {"text": "Single Field Index", "correct": false, "because": "Nur ein Feld"}, {"text": "Text Index", "correct": false, "because": "Für Textsuche"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Objekt in MongoDB ermöglicht komplexe Datenverarbeitung wie Filtern und Gruppieren?', 2, '[{"text": "Aggregation Pipeline", "correct": true, "because": "Verarbeitet Daten in Stufen"}, {"text": "Index", "correct": false, "because": "Optimiert Abfragen"}, {"text": "Dokument", "correct": false, "because": "Datenstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator wird häufig in der Aggregation Pipeline verwendet, um Daten zu filtern?', 2, '[{"text": "$match", "correct": true, "because": "Filtert Dokumente"}, {"text": "$group", "correct": false, "because": "Gruppiert Daten"}, {"text": "$sort", "correct": false, "because": "Sortiert Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft eines Indexes in MongoDB kann die Schreibgeschwindigkeit verringern?', 2, '[{"text": "Indexpflege", "correct": true, "because": "Zusätzliche Schreiboperationen"}, {"text": "Datengröße", "correct": false, "because": "Indirekt"}, {"text": "Abfragehäufigkeit", "correct": false, "because": "Kein direkter Einfluss"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Indizes gibt es in MongoDB?', 4, '[{"text": "Single Field Index", "correct": true, "because": "Ein Feld indiziert"}, {"text": "Compound Index", "correct": true, "because": "Mehrere Felder"}, {"text": "Text Index", "correct": true, "because": "Für Textsuche"}, {"text": "Join Index", "correct": false, "because": "Nicht in MongoDB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Indizes in MongoDB?', 3, '[{"text": "Schnellere Abfragen", "correct": true, "because": "Optimiert Zugriff"}, {"text": "Effizientere Sortierung", "correct": true, "because": "Sortierte Indizes"}, {"text": "Unterstützung für Suchoperationen", "correct": true, "because": "z.B. Textindizes"}, {"text": "Weniger Speicherbedarf", "correct": false, "because": "Mehr Speicher nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren sind typisch für die Aggregation Pipeline in MongoDB?', 4, '[{"text": "$match", "correct": true, "because": "Filtert Dokumente"}, {"text": "$group", "correct": true, "because": "Gruppiert Daten"}, {"text": "$sort", "correct": true, "because": "Sortiert Ergebnisse"}, {"text": "$insert", "correct": false, "because": "Keine Pipeline-Stufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen haben Indizes in MongoDB?', 3, '[{"text": "Bessere Leseleistung", "correct": true, "because": "Schnellere Abfragen"}, {"text": "Erhöhte Schreiblast", "correct": true, "because": "Indexpflege"}, {"text": "Mehr Speicherbedarf", "correct": true, "because": "Zusätzliche Struktur"}, {"text": "Schnellere Löschung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen kann die Aggregation Pipeline in MongoDB erfüllen?', 3, '[{"text": "Daten filtern", "correct": true, "because": "$match"}, {"text": "Daten gruppieren", "correct": true, "because": "$group"}, {"text": "Daten transformieren", "correct": true, "because": "$project"}, {"text": "Daten einfügen", "correct": false, "because": "Insert-Operation"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Indizes verbessern die Abfrageleistung. b) Sie haben keinen Einfluss auf die Schreibgeschwindigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abfragen ja, Schreiben nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Compound Index kann mehrere Felder abdecken. b) Die Aggregation Pipeline ist nur zum Filtern geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Felder ja, Pipeline vielseitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Aggregation Pipeline verarbeitet Daten in Stufen. b) Jede Stufe muss $match enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stufen ja, $match optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Indizes erhöhen den Speicherbedarf. b) Die Aggregation Pipeline kann Daten sortieren.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Speicher ja, Sortieren ja"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) $group in der Aggregation Pipeline aggregiert Daten. b) Indizes sind nur für Textfelder möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aggregation ja, Indizes vielseitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

